// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Base {
    uint256 count;
    uint256 start = block.number;
    bytes32 constant SEED = sha256(abi.encodePacked(uint256(7)));

    modifier counted() {
        count += 1;
        _;
        count += 2;
    }
}

Derived.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "Base.sol";

contract Derived is Base {
    function set(uint256 x) public counted returns (bytes32) {
        return SEED ^ bytes32(x);
    }
}
